G=("0 86" "99 111" "117 120" "122 125" "180 183" "199 199" "200 206" "255 258" "276 285" "295 296" "297 297" "298 299" "300 301" "350 359" "360 363" "368 371" "375 375" "413 413" "415 415" "420 420" "430 431" "470 489")
for s in $(seq 491 574) 575 576 577 578 579 580 581 582 583 584 585 586 587 588 589 590 591 592 593 594 595 596 597 598 599 600 601 602 603 604 605 606 607 608 609 610 611 612 613 614 616 618 619 620 621 622 623 624 615 617 626 627 628 629 630 631 644 800 801 802 803 804 805 806 936 979 978 977 976 975 974 973 972 971 970 969 968 967 966 965 964 963 962 961 960 959 958 957 956 955 954 953 952 951 950 949 948 947 946 945 944 942 941 940 939 938 937 935 934 933 932 930 929 928 927 926 925 924 923 921 920 919 918 917 916 915 914 913 912 911 910 909 907 906 905 904 903 902 901 900 849 848 847 846 845 844 843 842 841 840 838 837 836 835 834 833 832 831 830 829 828 827 826 825 824 823 822 820 821 816 817 819 814 815 813 807 808 809 810 811 812 632 633 634 635 636 637 638 639 640 641 645 646 647 648 649 650 651 652 654 655 656 657 658 659 660 661 662 663 664 665 666 667 668 669 670 671 672 673 674 675 676 677 678 679 680 681 682 683 684 685 686 687 688 689 690 691 692 693 694 695 696 697 698 699 850 851 852 854 855 856 858 859 860 861 862 864 865 866 867 869 870 871 872 873 874 875 876 877 878 879 880 881 882 883 884 885 886 887 888 889 890 891 892 893 894 895 896 898 899 1050 1051 1052 1053 1054 1055 1056 1057 1058 1059 1060 1061 700 701 702 703 704 705 706 707 708 709 710 711 712 713 714 715 716 717 718 719 720 721 722 723 724 725 726 727 728 729 730 731 732 733 734 735 736 737 738 739 740 741 742 743 744 745 746 747 748 749 750 751 752 753 754 755 759 760; do G+=("$s $s"); done
for g in "${G[@]}"; do
  set -- $g
  out=$(timeout 900 env CLAUDE_TEST_COPY=$COPY JAVA_TOOL_OPTIONS="$JAVA_TOOL_OPTIONS -Dclaude.startStage=$1 -Dclaude.endStage=$2" bash tools/test_in_copy.sh 2>&1 | tail -3)
